/* 학습 해설
 * Memory에 NUL 추가·길이 보존과 내부 종료
 * 정확한 길이를 아는 자료 뒤에 종료 byte를 더할 때 내부 NUL과 문자열 관찰을 구분합니다.
 * NULL source면NULL입니다. len+1을 kmalloc_track_caller로 만들고 성공하면 원본 len byte를 memcpy한 뒤 buf[len]=0을 씁니다. strnlen로 길이를 줄이지 않으므로 원본의 내부 NUL 뒤 byte도 len 안이면 복제됩니다.
 * 실제 읽을 수 있는 정확한 len과 len+1의 표현 범위를 보장합니다. 성공 allocation을 kfree합니다. strlen은 첫 내부 NUL에서 멈추므로 전체 복제 자료 길이와 다를 수 있습니다. 함수의 추가 종료만으로 binary가 임의 문자열 문법을 만족한다고 생각하지 않습니다.
 */
char *kmemdup_nul(const char *s, size_t len, gfp_t gfp)
{
	char *buf;

	if (!s)
		return NULL;

	buf = kmalloc_track_caller(len + 1, gfp);
	if (buf) {
		memcpy(buf, s, len);
		buf[len] = '\0';
	}
	return buf;
}
EXPORT_SYMBOL(kmemdup_nul);

static kmem_buckets *user_buckets __ro_after_init;

static int __init init_user_buckets(void)
{
	user_buckets = kmem_buckets_create("memdup_user", 0, 0, INT_MAX, NULL);

	return 0;
}
subsys_initcall(init_user_buckets);

/* 학습 해설
 * User Memory 복제·Buckets와 실패 정리
 * 사용자 주소를 kernel에서 소유한 복제본으로 바꾸며 할당 오류와 접근 오류를 나눕니다.
 * init_user_buckets는 memdup_user 이름의 kmem_buckets를 만들고 subsys_initcall로 연결합니다. memdup_user는 GFP_USER|NOWARN의 bucket allocation, vmemdup_user는 GFP_USER의 bucket valloc을 사용합니다. 할당 실패는 ERR_PTR(-ENOMEM), copy_from_user가 nonzero면 해당 allocation을 kfree 또는kvfree하고 ERR_PTR(-EFAULT)입니다.
 * IS_ERR로 오류를 검사하고 물리 연속 결과는 kfree, 비연속일 수 있는 결과는 kvfree합니다. copy_from_user의 nonzero는 못 복사한 byte가 있다는 뜻입니다. 사용자 pointer를 일반 kernel 문자열 함수로 직접 읽지 않습니다.
 */
void *memdup_user(const void __user *src, size_t len)
{
	void *p;

	p = kmem_buckets_alloc_track_caller(user_buckets, len, GFP_USER | __GFP_NOWARN);
	if (!p)
		return ERR_PTR(-ENOMEM);

	if (copy_from_user(p, src, len)) {
		kfree(p);
		return ERR_PTR(-EFAULT);
	}

	return p;
}
EXPORT_SYMBOL(memdup_user);

/**
 * vmemdup_user - duplicate memory region from user space
 *
 * @src: source address in user space
 * @len: number of bytes to copy
 *
 * Return: an ERR_PTR() on failure.  Result may be not
 * physically contiguous.  Use kvfree() to free.
 */

/* 학습 해설
 * User String 복제·길이의 NUL 포함
 * 사용자 문자열 길이 API가 끝 NUL을 포함한다는 계약과 읽기·복사의 두 단계를 배웁니다.
 * strnlen_user(s,n)은 NUL을 포함한 길이를 돌려줍니다. 0이면 EFAULT, n보다 크면 EINVAL입니다. 그 길이를 memdup_user로 복사하고 error pointer면 전달합니다. 성공 뒤 length-1을 NUL로 강제해 길이 검사 뒤 원본이 바뀌는 경우에도 목적 마지막을 종료합니다.
 * NUL 포함 최대 byte 수 n을 전달하고 IS_ERR로 검사해 성공 결과를 kfree합니다. 길이 확인과 복사 사이 user 자료가 바뀔 수 있어 전체 내용이 원자 snapshot이라고 가정하지 않습니다. 마지막 종료와 내용 검증은 다릅니다.
 */
char *strndup_user(const char __user *s, long n)
{
	char *p;
	long length;

	length = strnlen_user(s, n);

	if (!length)
		return ERR_PTR(-EFAULT);

	if (length > n)
		return ERR_PTR(-EINVAL);

	p = memdup_user(s, length);

	if (IS_ERR(p))
		return p;

	p[length - 1] = '\0';

	return p;
}
EXPORT_SYMBOL(strndup_user);

/**
 * memdup_user_nul - duplicate memory region from user space and NUL-terminate
 *
 * @src: source address in user space
 * @len: number of bytes to copy
 *
 * Return: an ERR_PTR() on failure.
 */

/* 학습 해설
 * User 자료에 NUL 추가·Sleep 가능한 경로
 * 사용자 binary 자료의 정확한 byte 수 뒤에 종료를 붙이며 pagefault 가능성과 allocation context를 연결합니다.
 * len+1을 GFP_KERNEL로 할당하고 실패면 ENOMEM입니다. copy_from_user가 nonzero면 kfree 뒤 EFAULT이며 성공하면 p[len]=0입니다. 원본 주석은 usercopy가 sleep·pagefault할 수 있어 GFP_ATOMIC·NOFS를 쓰는 것이 이 경로에 맞지 않다고 설명합니다.
 * 실제 user 주소와 제한된 len을 제공하고 IS_ERR로 검사해 kfree합니다. Atomic context에서 임의 usercopy를 안전하게 하려는 helper로 쓰지 않습니다. 원본이 내부 NUL을 포함해도 len byte를 복사하며 len+1 산술 범위를 상위에서 보장합니다.
 */
void *memdup_user_nul(const void __user *src, size_t len)
{
	char *p;

	/*
	 * Always use GFP_KERNEL, since copy_from_user() can sleep and
	 * cause pagefault, which makes it pointless to use GFP_NOFS
	 * or GFP_ATOMIC.
	 */
	p = kmalloc_track_caller(len + 1, GFP_KERNEL);
	if (!p)
		return ERR_PTR(-ENOMEM);

	if (copy_from_user(p, src, len)) {
		kfree(p);
		return ERR_PTR(-EFAULT);
	}
	p[len] = '\0';

	return p;
}
EXPORT_SYMBOL(memdup_user_nul);

/* Check if the vma is being used as a stack by this task */
int vma_is_stack_for_current(struct vm_area_struct *vma)
{

/* 학습 해설
 * VMA 보조·Stack 주소와 File 참조 교체
 * 가상 주소 구간과 backing file을 연결할 때 자료 필드 대입과 참조 수명 처리가 함께 필요합니다.
 * vma_set_file은 새 file을 get_file한 뒤 vm_file과 local file을 swap하고 이전 file을 fput합니다. 원본은 초기 VMA 설정 중에만 유효하고 anonymous VMA를 이 방식으로 바꾸면 안 된다고 명시합니다. vma_is_stack_for_current는 현재 stack pointer가 vm_start 이상·vm_end 이하인지 비교하는 보조 판정입니다.
 * 초기 설정과 file 수명 조건을 지켜 사용합니다. 살아 있는 임의 VMA를 단순 pointer 변경으로 다른 mapping으로 전환하지 않습니다. Stack helper의 inclusive 비교를 다른 VMA 탐색 API의 일반 end-exclusive 계약으로 대체하지 않습니다.
 */
void vma_set_file(struct vm_area_struct *vma, struct file *file)
{
	/* Changing an anonymous vma with this is illegal */
	get_file(file);
	swap(vma->vm_file, file);
	fput(file);
}
EXPORT_SYMBOL(vma_set_file);

#ifndef STACK_RND_MASK
#define STACK_RND_MASK (0x7ff >> (PAGE_SHIFT - 12))     /* 8MB of VA */
#endif

unsigned long randomize_stack_top(unsigned long stack_top)
{
	unsigned long random_variable = 0;

	if (current->flags & PF_RANDOMIZE) {
		random_variable = get_random_long();
		random_variable &= STACK_RND_MASK;
		random_variable <<= PAGE_SHIFT;
	}
#ifdef CONFIG_STACK_GROWSUP
	return PAGE_ALIGN(stack_top) + random_variable;
#else
	return PAGE_ALIGN(stack_top) - random_variable;

/* 학습 해설
 * Stack ASLR·Page Mask와 성장 방향
 * 프로세스 stack 시작을 page 단위로 움직이는 주소 무작위화에서 flag와 architecture 성장 방향을 읽습니다.
 * PF_RANDOMIZE가 있으면 get_random_long의 낮은 STACK_RND_MASK bit를 남기고 PAGE_SHIFT만큼 왼쪽 이동합니다. 없으면 random_variable은0입니다. 기본 mask는 page 크기에 따라 조정됩니다. PAGE_ALIGN(stack_top) 뒤 위로 자라는 설정은 더하고 일반 아래로 자라는 설정은 뺍니다.
 * 선택 architecture·page 크기·personality의 randomization 설정을 함께 확인합니다. 반환은 주소 배치 후보이며 그 범위에 실제 memory를 allocation하는 함수는 아닙니다. 난수 폭과 page alignment를 byte 수·entropy bit로 구분합니다.
 */
unsigned long randomize_stack_top(unsigned long stack_top)
{
	unsigned long random_variable = 0;

	if (current->flags & PF_RANDOMIZE) {
		random_variable = get_random_long();
		random_variable &= STACK_RND_MASK;
		random_variable <<= PAGE_SHIFT;
	}
#ifdef CONFIG_STACK_GROWSUP
	return PAGE_ALIGN(stack_top) + random_variable;
#else
	return PAGE_ALIGN(stack_top) - random_variable;
#endif
}

/**
 * randomize_page - Generate a random, page aligned address
 * @start:	The smallest acceptable address the caller will take.
 * @range:	The size of the area, starting at @start, within which the
 *		random address must fall.
 *
 * If @start + @range would overflow, @range is capped.
 *
 * NOTE: Historical use of randomize_range, which this replaces, presumed that
 * @start was already page aligned.  We now align it regardless.
 *
 * Return: A page aligned address within [start, start + range).  On error,
 * @start is returned.
 */

/* 학습 해설
 * Randomize Page·정렬과 Range 한도
 * 허용 주소 범위에서 page 정렬 후보를 선택하며 unsigned 산술과 caller의 입력 조건을 확인합니다.
 * start가 unaligned이면 다음 page까지의 차이를 range에서 빼고 start를 올려 정렬합니다. start+range overflow가 가능하면 range를 ULONG_MAX-start로 줄입니다. range를 PAGE_SHIFT만큼 오른쪽 이동해 page 개수를 만들고0이면 start, 아니면 get_random_long()%range를 page offset으로 바꿔 더합니다.
 * Alignment 차이를 감당할 수 있는 충분한 range를 제공합니다. 아주 작은 range는 첫 unsigned 뺄셈에서 underflow할 수 있으므로 이 helper가 모든 잘못된 범위를 자동 거부한다고 생각하지 않습니다. Modulo 선택을 편향 없는 암호학적 균등 난수 증명으로 확대하지 않습니다.
 */
unsigned long randomize_page(unsigned long start, unsigned long range)
{
	if (!PAGE_ALIGNED(start)) {
		range -= PAGE_ALIGN(start) - start;
		start = PAGE_ALIGN(start);
	}

	if (start > ULONG_MAX - range)
		range = ULONG_MAX - start;

	range >>= PAGE_SHIFT;

	if (range == 0)
		return start;

	return start + (get_random_long() % range << PAGE_SHIFT);
}

#ifdef CONFIG_ARCH_WANT_DEFAULT_TOPDOWN_MMAP_LAYOUT
unsigned long __weak arch_randomize_brk(struct mm_struct *mm)
{
	/* Is the current task 32bit ? */
	if (!IS_ENABLED(CONFIG_64BIT) || is_compat_task())
		return randomize_page(mm->brk, SZ_32M);

	return randomize_page(mm->brk, SZ_1G);

/* 학습 해설
 * Mmap 배치 선택·Legacy와 Top Down
 * 같은 mmap 호출도 프로세스 설정과 stack 제한에 따라 탐색 시작과 방향이 달라지는 이유를 배웁니다.
 * PF_RANDOMIZE이면 arch_mmap_rnd로 page random factor를 만듭니다. ADDR_COMPAT_LAYOUT·아래로 자라는 무제한 stack·legacy sysctl 조건이면 TASK_UNMAPPED_BASE+random에서 시작하고 MMF_TOPDOWN을 지웁니다. 그렇지 않으면 mmap_base가 stack limit·guard gap·random pad를 고려해 주소를 계산하고 TOPDOWN을 설정합니다. 별도 MMU fallback은 기본 base와 clear만 수행합니다.
 * CONFIG의 기본 topdown 선택과 compat task·mmap_rnd bits를 확인합니다. 주소 배치 정책과 실제 빈 VMA 검색·mapping allocation을 구분합니다. Stack growsup은 gap 계산의 별도 branch입니다.
 */
void arch_pick_mmap_layout(struct mm_struct *mm, struct rlimit *rlim_stack)
{
	unsigned long random_factor = 0UL;

	if (current->flags & PF_RANDOMIZE)
		random_factor = arch_mmap_rnd();

	if (mmap_is_legacy(rlim_stack)) {
		mm->mmap_base = TASK_UNMAPPED_BASE + random_factor;
		clear_bit(MMF_TOPDOWN, &mm->flags);
	} else {
		mm->mmap_base = mmap_base(random_factor, rlim_stack);
		set_bit(MMF_TOPDOWN, &mm->flags);
	}
}
#elif defined(CONFIG_MMU) && !defined(HAVE_ARCH_PICK_MMAP_LAYOUT)
void arch_pick_mmap_layout(struct mm_struct *mm, struct rlimit *rlim_stack)
{
	mm->mmap_base = TASK_UNMAPPED_BASE;
	clear_bit(MMF_TOPDOWN, &mm->flags);
}
#endif
#ifdef CONFIG_MMU
EXPORT_SYMBOL_IF_KUNIT(arch_pick_mmap_layout);
#endif

/* 학습 해설
 * Locked VM 회계·쓰기 Lock과 Memlock 한도
 * 잠근 page 수의 회계에서 byte 단위 제한과 page 단위 counter를 연결하고 실패 시 갱신을 막습니다.
 * __account_locked_vm은 mmap write lock을 요구합니다. 증가 때 bypass가 아니면 RLIMIT_MEMLOCK을 PAGE_SHIFT로 나눠 limit과 locked_vm+pages를 비교합니다. 넘으면ENOMEM, 정상일 때만 counter를 갱신합니다. 감소는 pages>locked_vm을 WARN하지만 뺄셈은 실행합니다. Wrapper account_locked_vm은 NULL mm·0page면0이며 lock을 잡고 current·CAP_IPC_LOCK bypass를 전달합니다.
 * Mm·task 참조 수명을 유지하고 직접 helper에는 write lock을 보장합니다. 증가 합·감소 범위는 caller가 올바른 page 회계로 관리합니다. WARN이 잘못된 감소를 되돌리는 exception이라고 생각하지 않습니다. Privilege bypass와 memory 접근 권한을 구분합니다.
 */
int __account_locked_vm(struct mm_struct *mm, unsigned long pages, bool inc,
			struct task_struct *task, bool bypass_rlim)
{
	unsigned long locked_vm, limit;
	int ret = 0;

	mmap_assert_write_locked(mm);

	locked_vm = mm->locked_vm;
	if (inc) {
		if (!bypass_rlim) {
			limit = task_rlimit(task, RLIMIT_MEMLOCK) >> PAGE_SHIFT;
			if (locked_vm + pages > limit)
				ret = -ENOMEM;
		}
		if (!ret)
			mm->locked_vm = locked_vm + pages;
	} else {
		WARN_ON_ONCE(pages > locked_vm);
		mm->locked_vm = locked_vm - pages;
	}

	pr_debug("%s: [%d] caller %ps %c%lu %lu/%lu%s\n", __func__, task->pid,
		 (void *)_RET_IP_, (inc) ? '+' : '-', pages << PAGE_SHIFT,
		 locked_vm << PAGE_SHIFT, task_rlimit(task, RLIMIT_MEMLOCK),
		 ret ? " - exceeded" : "");

/* 학습 해설
 * Kernel Mmap Wrapper·Security와 Lock 이후 처리
 * Mapping 생성 앞 권한 검사와 뒤 population·userfault 통지가 lock 범위와 어떻게 연결되는지 읽습니다.
 * security_mmap_file이 성공해야 killable mmap write lock을 잡습니다. Lock 실패는EINTR입니다. do_mmap은 pgoff와 populate·userfault list를 전달받고 반환 뒤 lock을 풀어 userfaultfd_unmap_complete를 호출합니다. populate가 있으면 mm_populate입니다. vm_mmap의 byte offset은 alignment·offset+PAGE_ALIGN(len) overflow 조건을 확인한 뒤 page offset으로 바뀝니다.
 * 원본의 unsigned long 반환이 성공 주소 또는 음수 errno 표현임을 확인하고 실제 caller의 오류 판정을 사용합니다. Wrapper 검사만으로 모든 len·주소·flag 문법이 완료됐다고 생각하지 않고 do_mmap 검증도 추적합니다. Userfault 완료와 population을 lock을 잡은 상태로 임의 재배치하지 않습니다.
 */
unsigned long vm_mmap_pgoff(struct file *file, unsigned long addr,
	unsigned long len, unsigned long prot,
	unsigned long flag, unsigned long pgoff)
{
	unsigned long ret;
	struct mm_struct *mm = current->mm;
	unsigned long populate;
	LIST_HEAD(uf);

	ret = security_mmap_file(file, prot, flag);
	if (!ret) {
		if (mmap_write_lock_killable(mm))
			return -EINTR;
		ret = do_mmap(file, addr, len, prot, flag, 0, pgoff, &populate,
			      &uf);
		mmap_write_unlock(mm);
		userfaultfd_unmap_complete(mm, &uf);
		if (populate)
			mm_populate(ret, populate);
	}
	return ret;
}

unsigned long vm_mmap(struct file *file, unsigned long addr,
	unsigned long len, unsigned long prot,
	unsigned long flag, unsigned long offset)

/* 학습 해설
 * KVMalloc 대체 경로·GFP와 Page 크기
 * 먼저 물리 연속 allocation을 시도하고 실패할 때 가상 연속 allocation으로 바꾸는 조건을 익힙니다.
 * 먼저 __kmalloc_node_noprof를 호출합니다. 성공 또는 요청이 PAGE_SIZE 이하이면 그대로 반환합니다. 큰 요청 실패에서 blocking을 허용하지 않는 flags면NULL, INT_MAX 초과면 경고 조건 뒤NULL입니다. 나머지는 VM_ALLOW_HUGE_VMAP을 주어 vmalloc range로 갑니다. kmalloc_gfp_adjust는 큰 요청에 NOWARN·필요시NORETRY를 추가하고 NOFAIL을 지웁니다.
 * 수면 가능한 GFP_KERNEL 호환 context와 적절한 크기를 제공합니다. 결과의 물리 연속을 가정하지 않고 kvfree합니다. Retry 정책은 첫 kmalloc 시도와 vmalloc fallback을 나눠 읽습니다. Atomic allocation에 임의 fallback을 기대하지 않습니다.
 */
void *__kvmalloc_node_noprof(DECL_BUCKET_PARAMS(size, b), gfp_t flags, int node)
{
	void *ret;

	/*
	 * It doesn't really make sense to fallback to vmalloc for sub page
	 * requests
	 */
	ret = __kmalloc_node_noprof(PASS_BUCKET_PARAMS(size, b),
				    kmalloc_gfp_adjust(flags, size),
				    node);
	if (ret || size <= PAGE_SIZE)
		return ret;

	/* non-sleeping allocations are not supported by vmalloc */
	if (!gfpflags_allow_blocking(flags))
		return NULL;

	/* Don't even allow crazy sizes */
	if (unlikely(size > INT_MAX)) {
		WARN_ON_ONCE(!(flags & __GFP_NOWARN));
		return NULL;
	}

	/*
	 * kvmalloc() can always use VM_ALLOW_HUGE_VMAP,
	 * since the callers already cannot assume anything
	 * about the resulting pointer, and cannot play
	 * protection games.
	 */

/* 학습 해설
 * KV 재할당·기존 자료 보존과 실패 Ownership
 * 자료를 더 큰 공간으로 옮길 때 새 할당 실패가 기존 pointer의 소유권을 없애지 않는 경로를 읽습니다.
 * Vmalloc 주소이면 vrealloc_noprof에 위임합니다. 아니면 조정 flags로 krealloc을 시도합니다. 실패하면 kvmalloc을 시도하고 또 실패하면NULL입니다. 새 allocation이 성공하고 이전p가 있으면 KASAN을 잠시 비활성화해 tag를 정리한p의 ksize만큼 복사한 뒤 다시 활성화하고 이전p를kfree합니다.
 * 같은 allocation에 재할당·해제를 동시에 호출하지 않습니다. 실패 반환은 기존p를 보관하여 계속 소유해야 합니다. 성공한 반환으로 pointer를 갱신합니다. ZERO 초기화 의미가 필요하면 처음부터 모든 후속 호출에서GFP_ZERO를 유지하라는 문서 조건을 지킵니다.
 */
void *kvrealloc_noprof(const void *p, size_t size, gfp_t flags)
{
	void *n;

	if (is_vmalloc_addr(p))
		return vrealloc_noprof(p, size, flags);

	n = krealloc_noprof(p, size, kmalloc_gfp_adjust(flags, size));
	if (!n) {
		/* We failed to krealloc(), fall back to kvmalloc(). */
		n = kvmalloc_noprof(size, flags);
		if (!n)
			return NULL;

		if (p) {
			/* We already know that `p` is not a vmalloc address. */
			kasan_disable_current();
			memcpy(n, kasan_reset_tag(p), ksize(p));
			kasan_enable_current();

			kfree(p);
		}
	}

	return n;
}

/* 학습 해설
 * Vmalloc Array·곱셈 검사와 Zero Flag
 * 가상 연속 배열의 총 크기를 계산할 때 overflow를 allocation 전에 검사하고 초기화 옵션을 전달합니다.
 * __vmalloc_array_noprof는 n×size의 check_mul_overflow 실패면 NULL, 성공하면 bytes를 __vmalloc_noprof에 전달합니다. vmalloc_array는 GFP_KERNEL입니다. __vcalloc은 받은 flags에 GFP_ZERO를 OR하고 vcalloc은 GFP_KERNEL|GFP_ZERO입니다. 원소 개수와 한 원소 byte 크기를 곱합니다.
 * NULL 실패를 검사하고 성공 결과는 해당 vmalloc 해제 계약을 사용합니다. Zero는 allocator에 요청하는 flag이며 이 wrapper에 별도 원소 생성자가 없습니다. Byte 0과 임의 자료형의 논리 초기화를 동일하게 보지 않습니다.
 */
void *__vmalloc_array_noprof(size_t n, size_t size, gfp_t flags)
{
	size_t bytes;

	if (unlikely(check_mul_overflow(n, size, &bytes)))
		return NULL;
	return __vmalloc_noprof(bytes, flags);
}
EXPORT_SYMBOL(__vmalloc_array_noprof);

/**
 * vmalloc_array - allocate memory for a virtually contiguous array.
 * @n: number of elements.
 * @size: element size.
 */
void *vmalloc_array_noprof(size_t n, size_t size)
{
	return __vmalloc_array_noprof(n, size, GFP_KERNEL);
}
EXPORT_SYMBOL(vmalloc_array_noprof);

/**
 * __vcalloc - allocate and zero memory for a virtually contiguous array.
 * @n: number of elements.
 * @size: element size.
 * @flags: the type of memory to allocate (see kmalloc).
 */

/* 학습 해설
 * Folio Mapping·Pointer Tag와 Swap 우선순위
 * Page 묶음의 mapping field가 항상 정상 주소인 것은 아니라는 tagged pointer 원리를 읽습니다.
 * folio_anon_vma는 mapping의 PAGE_MAPPING_FLAGS가 정확히 ANON인지 확인하고 표식 값을 빼서 anon_vma를 반환합니다. folio_mapping은 slab이면 NULL, swapcache면 swap_address_space로 갑니다. 나머지 mapping에 flag bit가 있으면 NULL이며 일반 pagecache mapping만 반환합니다.
 * Folio의 수명과 상태 동기화를 보장하고 반환 NULL을 처리합니다. Folio mapping과 사용자 VMA 주소를 같은 pointer로 보지 않습니다. Swapcache의 mapping은 swap 파일 자체의 mapping과 다르다는 문서 조건도 확인합니다.
 */
struct address_space *folio_mapping(struct folio *folio)
{
	struct address_space *mapping;

	/* This happens if someone calls flush_dcache_page on slab page */
	if (unlikely(folio_test_slab(folio)))
		return NULL;

	if (unlikely(folio_test_swapcache(folio)))
		return swap_address_space(folio->swap);

	mapping = folio->mapping;
	if ((unsigned long)mapping & PAGE_MAPPING_FLAGS)
		return NULL;

	return mapping;
}
EXPORT_SYMBOL(folio_mapping);

/**
 * folio_copy - Copy the contents of one folio to another.
 * @dst: Folio to copy to.
 * @src: Folio to copy from.
 *
 * The bytes in the folio represented by @src are copied to @dst.
 * Assumes the caller has validated that @dst is at least as large as @src.
 * Can be called in atomic context for order-0 folios, but if the folio is
 * larger, it may sleep.
 */

/* 학습 해설
 * Folio 복사·Page 반복과 중간 Poison 오류
 * 여러 page의 자료를 복사할 때 reschedule 위치와 중간 오류의 부분 결과를 읽습니다.
 * folio_copy는 source page 수만큼 copy_highpage를 반복하고 마지막이 아니면 cond_resched합니다. folio_mc_copy는 copy_mc_highpage가 실패하면 EHWPOISON으로 즉시 반환합니다. 성공한 앞 page를 되돌리는 rollback은 없습니다. 마지막 page 뒤에는 cond_resched를 추가하지 않습니다.
 * 목적 folio가 source 이상 크기임을 caller가 검사합니다. Order 0은 atomic context에서 가능하지만 큰 folio는 sleep할 수 있다는 문서를 따릅니다. Poison 오류에서 목적을 완전한 복제본으로 공개하지 않고 부분 결과 정책을 처리합니다.
 */
int folio_mc_copy(struct folio *dst, struct folio *src)
{
	long nr = folio_nr_pages(src);
	long i = 0;

	for (;;) {
		if (copy_mc_highpage(folio_page(dst, i), folio_page(src, i)))
			return -EHWPOISON;
		if (++i == nr)
			break;
		cond_resched();
	}

	return 0;
}
EXPORT_SYMBOL(folio_mc_copy);

int sysctl_overcommit_memory __read_mostly = OVERCOMMIT_GUESS;
int sysctl_overcommit_ratio __read_mostly = 50;
unsigned long sysctl_overcommit_kbytes __read_mostly;
int sysctl_max_map_count __read_mostly = DEFAULT_MAX_MAP_COUNT;
unsigned long sysctl_user_reserve_kbytes __read_mostly = 1UL << 17; /* 128MB */
unsigned long sysctl_admin_reserve_kbytes __read_mostly = 1UL << 13; /* 8MB */

int overcommit_ratio_handler(const struct ctl_table *table, int write, void *buffer,
		size_t *lenp, loff_t *ppos)

/* 학습 해설
 * Overcommit 정책 교체·Batch와 Per CPU 동기화
 * 느슨한 메모리 회계를 엄격한 정책으로 바꿀 때 공개 순서를 조절해 남은 CPU별 값을 합칩니다.
 * Write이면 임시 table.data를 new_policy에 연결해 minmax parser로 읽습니다. 오류나 값 미설정이면 반환합니다. 정상 정책에는 먼저 mm_compute_batch를 적용하고 NEVER로 바꾸면 schedule_on_each_cpu(sync_overcommit_as)로 각 CPU counter를 동기화합니다. 마지막에 sysctl_overcommit_memory를 대입합니다. Read는 기존 table을 parser에 전달합니다.
 * 정책 값을 정상 sysctl 인터페이스로 변경하고 회계 batch·CPU별 누적·전역 정책의 순서를 이해합니다. 전역 변수만 직접 대입해 동일 전환이 처리됐다고 생각하지 않습니다. 이 helper의 CPU 동기화를 임의 객체 수명 보호나 모든 memory barrier로 쓰지 않습니다.
 */
int overcommit_policy_handler(const struct ctl_table *table, int write, void *buffer,
		size_t *lenp, loff_t *ppos)
{
	struct ctl_table t;
	int new_policy = -1;
	int ret;

	/*
	 * The deviation of sync_overcommit_as could be big with loose policy
	 * like OVERCOMMIT_ALWAYS/OVERCOMMIT_GUESS. When changing policy to
	 * strict OVERCOMMIT_NEVER, we need to reduce the deviation to comply
	 * with the strict "NEVER", and to avoid possible race condition (even
	 * though user usually won't too frequently do the switching to policy
	 * OVERCOMMIT_NEVER), the switch is done in the following order:
	 *	1. changing the batch
	 *	2. sync percpu count on each CPU
	 *	3. switch the policy
	 */
	if (write) {
		t = *table;
		t.data = &new_policy;
		ret = proc_dointvec_minmax(&t, write, buffer, lenp, ppos);
		if (ret || new_policy == -1)
			return ret;

		mm_compute_batch(new_policy);

/* 학습 해설
 * Commit Limit·RAM·Huge Page·Swap의 단위
 * 메모리 예약 허용 한도가 실제 현재 물리 사용량과 다르다는 점을 page 단위 공식으로 익힙니다.
 * overcommit_kbytes가 있으면 PAGE_SHIFT-10으로 나눠 page 수를 구합니다. 아니면 totalram_pages-hugetlb_total_pages에 ratio를 곱해100으로 나눕니다. 마지막에 total_swap_pages를 더합니다. vm_memory_committed는 vm_committed_as의 positive sum을 반환하며 counter는 SMP cacheline에 별도 정렬됩니다.
 * 한도의 단위를 page로 맞춰 비교하고 reservation 회계와 실제 resident memory를 구분합니다. Huge page를 제외하는 이유와 swap 추가를 공식에 연결합니다. 전역 변수의 초기 ratio50·user reserve128MiB·admin reserve8MiB는 이 고정 버전의 기본 값이며 runtime 설정을 따로 읽습니다.
 */
unsigned long vm_commit_limit(void)
{
	unsigned long allowed;

	if (sysctl_overcommit_kbytes)
		allowed = sysctl_overcommit_kbytes >> (PAGE_SHIFT - 10);
	else
		allowed = ((totalram_pages() - hugetlb_total_pages())
			   * sysctl_overcommit_ratio / 100);
	allowed += total_swap_pages;

	return allowed;
}

/*
 * Make sure vm_committed_as in one cacheline and not cacheline shared with
 * other variables. It can be updated by several CPUs frequently.
 */
struct percpu_counter vm_committed_as ____cacheline_aligned_in_smp;

/*
 * The global memory commitment made in the system can be a metric
 * that can be used to drive ballooning decisions when Linux is hosted
 * as a guest. On Hyper-V, the host implements a policy engine for dynamically
 * balancing memory across competing virtual machines that are hosted.
 * Several metrics drive this policy engine including the guest reported
 * memory commitment.
 *
 * The time cost of this is very low for small platforms, and for big
 * platform like a 2S/36C/72T Skylake server, in worst case where
 * vm_committed_as's spinlock is under severe contention, the time cost
 * could be about 30~40 microseconds.
 */

/* 학습 해설
 * 메모리 예약 허용·먼저 회계하고 실패 복원
 * 요청을 예약 회계에 더한 뒤 정책별로 승인하거나 되돌리는 과정을 단계별로 읽습니다.
 * 먼저 vm_acct_memory(pages)를 실행합니다. ALWAYS는 성공, GUESS는 요청 pages가 RAM+swap보다 크면 실패입니다. 엄격 경로는 commit limit에서 비관리자 reserve와 process total_vm/32·user reserve 중 작은 값을 뺍니다. Positive committed read가 allowed보다 작아야 성공입니다. 실패는 경고 후 vm_unacct_memory로 요청을 반납하고ENOMEM입니다.
 * 이 helper의 승인과 실제 page allocation 성공을 구분합니다. Policy·cap_sys_admin·mm 유무를 올바르게 전달하고 예약 회계의 다른 단계와 중복 증가·감소하지 않습니다. 엄격 비교가 <=가 아니라 <임을 문제에서 확인합니다.
 */
int __vm_enough_memory(struct mm_struct *mm, long pages, int cap_sys_admin)
{
	long allowed;
	unsigned long bytes_failed;

	vm_acct_memory(pages);

	/*
	 * Sometimes we want to use more memory than we have
	 */
	if (sysctl_overcommit_memory == OVERCOMMIT_ALWAYS)
		return 0;

	if (sysctl_overcommit_memory == OVERCOMMIT_GUESS) {
		if (pages > totalram_pages() + total_swap_pages)
			goto error;
		return 0;
	}

	allowed = vm_commit_limit();
	/*
	 * Reserve some for root
	 */
	if (!cap_sys_admin)
		allowed -= sysctl_admin_reserve_kbytes >> (PAGE_SHIFT - 10);

/* 학습 해설
 * Get Cmdline·범위 Snapshot과 종료 보정
 * 다른 task의 명령행을 읽을 때 mm 참조와 주소 범위 lock을 보관하되 최종 내용이 원자 snapshot은 아닌 이유를 배웁니다.
 * get_task_mm으로 참조를 얻고 mm가 없거나 arg_end가 아직0이면0입니다. arg_lock으로 arg·env 범위를 복사한 뒤 풀고 access_process_vm으로 buflen 한도 안을 읽습니다. 마지막 NUL이 덮이고 아직 공간이 있으면 내부 NUL까지 길이를 줄이거나 env 영역을 이어 읽어 strnlen으로 제한합니다. 모든 mm 경로는 mmput합니다.
 * 실제 writable 목적과 nonnegative 길이를 제공합니다. 반환 byte 수를 사용하고 끝 NUL 보장이 없으므로 문자열 출력은 caller가 공간을 남겨 종료합니다. User가 argument 내용을 바꿀 수 있어 범위 snapshot과 전체 byte 일관성을 구분합니다.
 */
int get_cmdline(struct task_struct *task, char *buffer, int buflen)
{
	int res = 0;
	unsigned int len;
	struct mm_struct *mm = get_task_mm(task);
	unsigned long arg_start, arg_end, env_start, env_end;
	if (!mm)
		goto out;
	if (!mm->arg_end)
		goto out_mm;	/* Shh! No looking before we're done */

	spin_lock(&mm->arg_lock);
	arg_start = mm->arg_start;
	arg_end = mm->arg_end;
	env_start = mm->env_start;
	env_end = mm->env_end;
	spin_unlock(&mm->arg_lock);

	len = arg_end - arg_start;

	if (len > buflen)
		len = buflen;

	res = access_process_vm(task, arg_start, buffer, len, FOLL_FORCE);

	/*
	 * If the nul at the end of args has been overwritten, then
	 * assume application is using setproctitle(3).
	 */

/* 학습 해설
 * Page 비교·Local Mapping의 역순 해제
 * 직접 접근하기 어려운 page를 잠시 매핑해 비교하고 local mapping stack을 올바른 순서로 해제합니다.
 * Generic weak memcmp_pages는 page1과page2를 kmap_local_page로 매핑하고 PAGE_SIZE를 memcmp합니다. 두 번째 주소부터 kunmap_local하고 첫 번째를 해제한 뒤 비교 결과를 반환합니다. Weak 구현이라 architecture가 대체할 수 있습니다.
 * 유효 page 수명과 비교 동안 자료 변경의 동기화를 보장합니다. Local mapping 주소를 저장해 다른 context에서 재사용하지 않습니다. 반환은 같음0·차이부호이며 전체 folio를 한 번에 비교하는 함수가 아닙니다.
 */
int __weak memcmp_pages(struct page *page1, struct page *page2)
{
	char *addr1, *addr2;
	int ret;

	addr1 = kmap_local_page(page1);
	addr2 = kmap_local_page(page2);
	ret = memcmp(addr1, addr2, PAGE_SIZE);
	kunmap_local(addr2);
	kunmap_local(addr1);
	return ret;
}

#ifdef CONFIG_PRINTK
/**
 * mem_dump_obj - Print available provenance information
 * @object: object for which to find provenance information.
 *
 * This function uses pr_cont(), so that the caller is expected to have
 * printed out whatever preamble is appropriate.  The provenance information
 * depends on the type of object and on how much debugging is enabled.
 * For example, for a slab-cache object, the slab name is printed, and,
 * if available, the return address and stack trace from the allocation
 * and last free path of that object.
 */
void mem_dump_obj(void *object)

/* 학습 해설
 * 객체 Provenance·Debug 설정과 주소 분류
 * 문제 pointer의 allocation 출처를 출력할 때 debug 정보의 가용성과 분류 순서를 확인합니다.
 * CONFIG_PRINTK이면 먼저 kmem_dump_obj, 그다음 vmalloc_dump_obj가 출처를 출력할 수 있는지 시도합니다. 둘 다 못하면 vmalloc 주소·유효 일반 주소·NULL·ZERO_SIZE_PTR·기타 순서로 type 문자열을 선택해 pr_cont합니다. Source 설명은 slab 이름과 debug 설정에 따라 allocation·free stack 정보가 있을 수 있다고 합니다.
 * Caller가 먼저 적절한 출력 preamble을 기록하고 이 함수로 이어 출력합니다. 정보 가용성이 설정마다 다름을 확인하고 provenance 출력이 pointer 접근의 안전성 검증을 대신한다고 생각하지 않습니다. 관찰한 자료를 수정하거나 allocation을 해제하는 함수는 아닙니다.
 */
void mem_dump_obj(void *object)
{
	const char *type;

	if (kmem_dump_obj(object))
		return;

	if (vmalloc_dump_obj(object))
		return;

	if (is_vmalloc_addr(object))
		type = "vmalloc memory";
	else if (virt_addr_valid(object))
		type = "non-slab/vmalloc memory";
	else if (object == NULL)
		type = "NULL pointer";
	else if (object == ZERO_SIZE_PTR)
		type = "zero-size pointer";
	else
		type = "non-paged memory";

	pr_cont(" %s\n", type);
}
EXPORT_SYMBOL_GPL(mem_dump_obj);
#endif

/* 학습 해설
 * Page Offline·Reader와 전환 Writer의 RW Semaphore
 * Page 내용을 읽는 동안 driver가 접근 불가능 상태로 바꾸는 경쟁을 reader/writer 프로토콜로 막습니다.
 * 공통 page_offline_rwsem에 freeze는 down_read, thaw는 up_read입니다. Driver의 begin은 down_write, end는 up_write입니다. Frozen reader가 있으면 writer의 PageOffline 전환이 기다리고 writer가 전환 중이면 새 reader가 접근 구간에 들어가지 못합니다. Reader들은 공유할 수 있고 writer는 배타적입니다.
 * 자료를 확인하고 읽는 필요한 구간을 freeze/thaw로 감싸고 전환하는 driver는begin/end를 맞춥니다. 이 프로토콜에 참여하지 않는 임의 writer까지 자동 보호하지 않습니다. Page 참조·물리 수명·다른 상태 전환의 lock은 별도로 보장합니다.
 */
void page_offline_freeze(void)
{
	down_read(&page_offline_rwsem);
}

void page_offline_thaw(void)
{
	up_read(&page_offline_rwsem);
}

void page_offline_begin(void)
{
	down_write(&page_offline_rwsem);
}
EXPORT_SYMBOL(page_offline_begin);

void page_offline_end(void)
{
	up_write(&page_offline_rwsem);
}
EXPORT_SYMBOL(page_offline_end);

#ifndef flush_dcache_folio
void flush_dcache_folio(struct folio *folio)
{
	long i, nr = folio_nr_pages(folio);

/* 학습 해설
 * Folio Cache Flush·Architecture Fallback 반복
 * CPU cache 유지 기능을 page 묶음에 적용할 때 architecture 대체 경로와 실제 반복 단위를 확인합니다.
 * flush_dcache_folio가 별도로 정의되어 있지 않으면 generic 함수는 folio_nr_pages를 구하고 각 folio_page에 flush_dcache_page를 호출합니다. 한 함수 이름으로 큰 folio를 처리하지만 실제 fallback은 page별 반복입니다. 선택 architecture의 flush 구현이 cache 유지 의미를 정합니다.
 * 유효한 folio와 해당 memory 변경·접근 프로토콜에서 사용합니다. 이름의 flush를 저장장치 fsync·파일 영속화와 동일하게 쓰지 않습니다. Architecture가 제공하면 이 fallback이 선택되지 않습니다.
 */
