 * 반환 코드를 먼저 확인한 뒤 출력값을 사용합니다. 출력된 32bit hash를 실제 주소로 역참조하거나 충돌 없는 전역 ID로 사용하지 않습니다. 같은 pointer의 표시에 쓰이는 정책이며 hash 충돌 가능성은 존재합니다.
 */
static inline int __ptr_to_hashval(const void *ptr, unsigned long *hashval_out)
{
	unsigned long hashval;

	if (!READ_ONCE(filled_random_ptr_key))
		return -EBUSY;

	/* Pairs with smp_wmb() after writing ptr_key. */
	smp_rmb();

#ifdef CONFIG_64BIT
	hashval = (unsigned long)siphash_1u64((u64)ptr, &ptr_key);
	/*
	 * Mask off the first 32 bits, this makes explicit that we have
	 * modified the address (and 32 bits is plenty for a unique ID).
	 */
	hashval = hashval & 0xffffffff;
#else
	hashval = (unsigned long)siphash_1u32((u32)ptr, &ptr_key);
#endif
	*hashval_out = hashval;
	return 0;
}

int ptr_to_hashval(const void *ptr, unsigned long *hashval_out)
{

/* 학습 해설
 * 기본 Pointer 출력·Hash와 준비 전 Placeholder
 * 부팅 초기부터 로그가 나오는 상황에서 주소 노출 정책과 key 미준비 처리를 연결합니다.
 * ptr_to_id는 NULL과 error pointer에는 실제 값 표시 보조를 사용합니다. Debug weak 설정이면 hash_long을 사용하고, 일반 경로에서 key가 아직 없으면 주소 크기에 맞는 ptrval placeholder를 error_string으로 출력합니다. 준비된 값은 pointer_string으로 표시합니다. default_pointer는 no_hash_pointers 설정이면 실제 주소를 출력하고 그렇지 않으면 ptr_to_id를 호출합니다.
 * 기본 출력, 명시적 no_hash_pointers 설정, 조기 weak debug 경로를 구분합니다. Key가 없을 때 placeholder를 실제 값 0이나 객체 부재로 해석하지 않습니다. NULL·error 표현은 실제 객체 주소가 아니라 특별 값이라는 원본 설명과 연결합니다.
 */
static char *ptr_to_id(char *buf, char *end, const void *ptr,
		       struct printf_spec spec)
{
	const char *str = sizeof(ptr) == 8 ? "(____ptrval____)" : "(ptrval)";
	unsigned long hashval;
	int ret;

	/*
	 * Print the real pointer value for NULL and error pointers,
	 * as they are not actual addresses.
	 */
	if (IS_ERR_OR_NULL(ptr))
		return pointer_string(buf, end, ptr, spec);

	/* When debugging early boot use non-cryptographically secure hash. */
	if (unlikely(debug_boot_weak_hash)) {
		hashval = hash_long((unsigned long)ptr, 32);
		return pointer_string(buf, end, (const void *)hashval, spec);
	}

	ret = __ptr_to_hashval(ptr, &hashval);
	if (ret) {
		spec.field_width = 2 * sizeof(ptr);
		/* string length must be less than default_width */
		return error_string(buf, end, str, spec);
	}

