static noinline_for_stack
char *symbol_string(char *buf, char *end, void *ptr,
		    struct printf_spec spec, const char *fmt)
{

/* 학습 해설
 * Symbol 출력·Kallsyms와 Build ID 분기
 * 로그에 주소 대신 함수 이름과 offset을 표시할 때 symbol 정보 설정과 format suffix가 선택하는 경로를 배웁니다.
 * fmt[1]==R이면 __builtin_extract_return_addr로 return address 표현을 조정합니다. CONFIG_KALLSYMS에서는 B·Bb에 backtrace 또는 build ID backtrace, S의 b·Rb suffix에 build ID symbol, s에 offset 없는 symbol, 나머지에 일반 symbol을 사용합니다. KALLSYMS가 없으면 pointer 크기 폭의 special_hex_number를 출력합니다.
 * 사용한 suffix와 커널 symbol 정보 설정을 확인합니다. Symbol이 없는 numeric fallback을 formatter 실패로 단정하지 않습니다. Build ID 표시와 실제 실행 파일 식별의 관계를 읽고 주소가 유효 코드 위치인지 caller의 계약을 확인합니다.
 */
char *symbol_string(char *buf, char *end, void *ptr,
		    struct printf_spec spec, const char *fmt)
{
	unsigned long value;
#ifdef CONFIG_KALLSYMS
	char sym[KSYM_SYMBOL_LEN];
#endif

	if (fmt[1] == 'R')
		ptr = __builtin_extract_return_addr(ptr);
	value = (unsigned long)ptr;

#ifdef CONFIG_KALLSYMS
	if (*fmt == 'B' && fmt[1] == 'b')
		sprint_backtrace_build_id(sym, value);
	else if (*fmt == 'B')
		sprint_backtrace(sym, value);
	else if (*fmt == 'S' && (fmt[1] == 'b' || (fmt[1] == 'R' && fmt[2] == 'b')))
		sprint_symbol_build_id(sym, value);
	else if (*fmt != 's')
		sprint_symbol(sym, value);
	else
		sprint_symbol_no_offset(sym, value);

	return string_nocheck(buf, end, sym, spec);
#else

/* 학습 해설
 * Hex Buffer 출력·개수와 Separator
 * 한 byte를 두 hex 문자로 출력할 때 입력 개수와 출력 폭이라는 이름이 어떻게 연결되는지 배웁니다.
 * field_width=0이면 입력 pointer 검사도 하기 전에 바로 반환합니다. 기본 len은 1이고 양수 width는 min(width,64)개의 입력 byte를 뜻합니다. fmt의 C는 colon, D는 hyphen, N은 separator 없음, 그 외는 space입니다. 각 byte의 높은 nibble과 낮은 nibble을 출력하고 마지막 byte 뒤에는 separator를 넣지 않습니다.
 * Width를 완성 문자열의 글자 수 대신 입력 byte 개수로 제공합니다. 유효 입력 길이를 보장하고 NUL 종료는 상위 출력 함수의 계약을 따릅니다. 이 함수의 64byte 제한을 다른 pointer formatter에도 동일하게 적용하지 않습니다.
 */
char *hex_string(char *buf, char *end, u8 *addr, struct printf_spec spec,
		 const char *fmt)
{
	int i, len = 1;		/* if we pass '%ph[CDN]', field width remains
				   negative value, fallback to the default */
	char separator;

	if (spec.field_width == 0)
		/* nothing to print */
		return buf;

	if (check_pointer(&buf, end, addr, spec))
		return buf;

	switch (fmt[1]) {
	case 'C':
		separator = ':';
		break;
	case 'D':
		separator = '-';
		break;
	case 'N':
		separator = 0;
		break;
	default:
		separator = ' ';

/* 학습 해설
 * Bitmap 표시·32bit Chunk와 연속 범위
 * 같은 bit 집합을 hex 묶음이나 범위 목록으로 표시하는 두 방식의 자료 읽기 순서를 이해합니다.
 * bitmap_string은 width를 bit 수로 받아 가장 높은 32bit chunk부터 내려갑니다. 첫 부분 chunk에는 필요한 bit mask와 ceil(bits/4) hex 폭을 사용하고 다음은 32bit씩 comma로 연결합니다. bitmap_list_string은 for_each_set_bitrange의 [rbot,rtop) 구간을 받아 한 bit면 rbot만, 연속이면 rbot부터 rtop-1까지 hyphen으로 표시합니다.
 * 유효 bitmap 저장공간과 의미 있는 bit 수를 제공합니다. Hex 표현의 높은 chunk 순서와 메모리 word 순서를 혼동하지 않습니다. 범위 iterator의 exclusive 끝을 그대로 출력하면 한 bit 더 표시하게 됩니다.
 */
char *bitmap_string(char *buf, char *end, const unsigned long *bitmap,
		    struct printf_spec spec, const char *fmt)
{
	const int CHUNKSZ = 32;
	int nr_bits = max_t(int, spec.field_width, 0);
	int i, chunksz;
	bool first = true;

	if (check_pointer(&buf, end, bitmap, spec))
		return buf;

	/* reused to print numbers */
	spec = (struct printf_spec){ .flags = SMALL | ZEROPAD, .base = 16 };

	chunksz = nr_bits & (CHUNKSZ - 1);
	if (chunksz == 0)
		chunksz = CHUNKSZ;

	i = ALIGN(nr_bits, CHUNKSZ) - CHUNKSZ;
	for (; i >= 0; i -= CHUNKSZ) {
		u32 chunkmask, val;
		int word, bit;

		chunkmask = ((1ULL << chunksz) - 1);
		word = i / BITS_PER_LONG;
		bit = i % BITS_PER_LONG;

/* 학습 해설
 * MAC 표시·순서 반전과 구분자
 * 6byte 주소의 저장 순서와 사람이 읽는 구분자 표현을 분리하여 이해합니다.
 * 입력 pointer를 확인한 뒤 6byte를 hex_byte_pack으로 임시 문자열에 저장합니다. R suffix는 addr[5-i]로 byte 순서를 반전하고 기본 colon을 사용합니다. F는 hyphen을 선택합니다. fmt[0]==M일 때만 byte 사이에 separator를 넣고 소문자 m 형태는 구분하지 않습니다. 내부 NUL 뒤 string_nocheck로 외부 출력합니다.
 * 6byte의 유효 자료를 제공하고 선택한 format의 대소문자·suffix를 확인합니다. R은 byte 배열 표시 순서 변경이지 각 byte bit 반전이 아닙니다. 이 helper는 NIC 설정이나 주소 변경을 수행하지 않습니다.
 */
char *mac_address_string(char *buf, char *end, u8 *addr,
			 struct printf_spec spec, const char *fmt)
{
	char mac_addr[sizeof("xx:xx:xx:xx:xx:xx")];
	char *p = mac_addr;
	int i;
	char separator;
	bool reversed = false;

	if (check_pointer(&buf, end, addr, spec))
		return buf;

	switch (fmt[1]) {
	case 'F':
		separator = '-';
		break;

	case 'R':
		reversed = true;
		fallthrough;

	default:
		separator = ':';
		break;
	}

/* 학습 해설
 * IPv4 표시·Byte Order와 세 자리 Zero
 * Network 자료를 출력할 때 endian과 선택 format이 octet 순서를 어떻게 바꾸는지 이해합니다.
 * 기본 n·b는 addr[0]부터, l은 addr[3]부터 역순, h는 선택 host endian에 따라 순서를 정합니다. 각 octet은 put_dec_trunc8로 역순 decimal을 만들고 다시 뒤집습니다. fmt[0]==i이면 각 octet을 세 자리로 앞 0을 채우며 I이면 필요한 자리만 표시합니다. Octet 사이 dot과 내부 NUL을 추가합니다.
 * 실제 자료의 byte order와 n·b·l·h format을 맞춥니다. Host order와 network order를 문자열의 endian이라고 뭉뚱그리지 않습니다. 낮은 수준 ip4_string의 buffer는 최대 IPv4 문자열과 NUL을 담도록 caller가 준비합니다.
 */
char *ip4_string(char *p, const u8 *addr, const char *fmt)
{
	int i;
	bool leading_zeros = (fmt[0] == 'i');
	int index;
	int step;

	switch (fmt[2]) {
	case 'h':
#ifdef __BIG_ENDIAN
		index = 0;
		step = 1;
#else
		index = 3;
		step = -1;
#endif
		break;
	case 'l':
		index = 3;
		step = -1;
		break;
	case 'n':
	case 'b':
	default:
		index = 0;
		step = 1;

/* 학습 해설
 * IPv6 기본 표시·고정 Hex와 Colon
 * 128bit 주소를 byte 배열에서 읽어 출력할 때 16bit 묶음과 문자열 모드의 차이를 배웁니다.
 * 8회 반복에서 byte 두 개씩 hex_byte_pack으로 네 자리 hex를 만듭니다. 대문자 I이면 마지막 묶음을 제외하고 colon을 붙이며 소문자 i는 separator 없이 이어 붙입니다. 이 기본 함수는 모든 묶음의 선행 0을 유지하고 끝 NUL을 저장합니다. ip6_addr_string은 I와 c suffix 조합일 때만 별도 compressed 함수를 선택합니다.
 * 16byte 자료를 제공하고 고정 표현과 압축 표현을 구분합니다. 여기에는 길이 0 run 탐색이 없습니다. Network byte 순서의 두 byte를 그대로 hex로 변환하는 단계와 숫자를 host order로 변환하는 단계를 구분합니다.
 */
char *ip6_string(char *p, const char *addr, const char *fmt)
{
	int i;

	for (i = 0; i < 8; i++) {
		p = hex_byte_pack(p, *addr++);
		p = hex_byte_pack(p, *addr++);
		if (fmt[0] == 'I' && i != 7)
			*p++ = ':';
	}
	*p = '\0';

	return p;
}

static noinline_for_stack
char *ip6_addr_string(char *buf, char *end, const u8 *addr,
		      struct printf_spec spec, const char *fmt)
{
	char ip6_addr[sizeof("xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:255.255.255.255")];

	if (fmt[0] == 'I' && fmt[2] == 'c')
		ip6_compressed_string(ip6_addr, addr);
	else
		ip6_string(ip6_addr, addr, fmt);

/* 학습 해설
 * IPv6 압축·최장 Zero Run과 동률 처리
